def eval_npi(expression):
    pile = []
    for token in expression.split():
        if token in '+-*/':
            b = pile.pop()
            a = pile.pop()
            if token == '+':
                pile.append(a + b)
            elif token == '-':
                pile.append(a - b)
            elif token == '*':
                pile.append(a * b)
            elif token == '/':
                pile.append(a / b)
        else:
            pile.append(float(token))
    return pile[0]
